mapper.select:
SELECT h.* FROM agri_prod_harvest_record h
WHERE h.deleted = 0 AND h.tenant_id = #{tenantId}

    AND h.crop_name LIKE CONCAT('%', #{dto.cropName}, '%')


    AND h.farm_id = #{dto.farmId}


    AND h.plot_id = #{dto.plotId}


    AND h.quality_grade = #{dto.qualityGrade}


    AND h.status = #{dto.status}


    AND h.harvest_date >= #{dto.startDate}


    AND h.harvest_date <= #{dto.endDate}

ORDER BY h.harvest_date DESC
